def convert_characters(input_text: str, char_map: str, output: list) -> tuple:
    """
    Universal character converter using a character mapping.
    char_map format: 'source_char1:target_char1,source_char2:target_char2'
    Any character not in the map passes through unchanged.
    """
    try:
        # Parse the character map
        mapping = {}
        if char_map.strip():
            for pair in char_map.split(','):
                if ':' in pair:
                    source, target = pair.split(':', 1)
                    mapping[source] = target

        # Apply the mapping
        result = ''.join(mapping.get(char, char) for char in input_text)

        return result, {"status": {"value": 0, "reason": "Success"}}

    except Exception as e:
        return "", {"status": {"value": 1, "reason": f"Character conversion failed: {e}"}}

