import requests
import time
import json
import re
import logging
import os
from typing import Dict, Union, Optional, Tuple, Any
from urllib.parse import urlparse
from ftplib import FTP, FTP_TLS, error_perm
from io import BytesIO
from os.path import dirname, basename

# --- HTTP Helper with Retry Logic ---
def _fetch_http(url: str, headers: Optional[dict], timeout_seconds: Optional[int]) -> Tuple[bytes, Dict[str, Any]]:
    parsed_url = urlparse(url)
    is_secure_protocol = parsed_url.scheme == 'https'
    if is_secure_protocol:
        hostname = parsed_url.hostname
        if not hostname or re.match(r'^((127\.)|(10\.)|(172\.(1[6-9]|2[0-9]|3[0-1])\.)|(192\.168\.)|(0\.)|^(localhost))', hostname):
            raise ValueError('Security Error: HTTPS URL targets a forbidden internal address.')
        effective_timeout = timeout_seconds if timeout_seconds is not None else 30
    else:
        effective_timeout = timeout_seconds if timeout_seconds is not None else 600

    max_retries: int = 3
    retry_delays = [5, 10, 15]
    retryable_status_codes = {408, 429, 500, 502, 503, 504}

    for attempt in range(max_retries):
        try:
            response = requests.get(url, headers=headers, timeout=effective_timeout)
            if response.status_code == 200:
                metadata = {'status_code': response.status_code, 'headers': dict(response.headers)}
                return response.content, metadata
            if response.status_code in retryable_status_codes and attempt < max_retries - 1:
                time.sleep(retry_delays[attempt])
                continue
            response.raise_for_status() # Raise exception for non-retryable bad status
        except requests.exceptions.RequestException as e:
            logging.warning(f"HTTP attempt {attempt + 1}/{max_retries} failed for {url}: {e}")
            if attempt < max_retries - 1:
                time.sleep(retry_delays[attempt])
            else:
                raise # Re-raise the last exception if all retries fail
    raise ValueError("HTTP fetch failed after all retries.")

# --- FTP Helper with Retry Logic ---
def _fetch_ftp(url: str, username: str, password: str, passive_mode: bool) -> Tuple[Union[bytes, str], Dict[str, Any]]:
    parsed_url = urlparse(url)
    ftp_host = parsed_url.hostname
    remote_path = parsed_url.path
    port = parsed_url.port or (21 if parsed_url.scheme == 'ftp' else 990)
    is_ftps = parsed_url.scheme == 'ftps'

    def is_permanent_failure(e: Exception) -> bool:
        if isinstance(e, error_perm):
            return any(code in str(e).lower() for code in ["550", "530", "553", "501", "502"])
        return False

    max_retries = 5
    backoff_base = 1
    for attempt in range(1, max_retries + 1):
        try:
            ftp = FTP_TLS(timeout=10) if is_ftps else FTP(timeout=10)
            ftp.connect(ftp_host, port)
            ftp.login(user=username, passwd=password)
            if is_ftps: ftp.prot_p()
            ftp.set_pasv(passive_mode)
            if remote_path.endswith('/'):
                lines = []
                ftp.retrlines(f'NLST {remote_path.rstrip("/")}', lines.append)
                result = '\n'.join(lines)
                metadata = {'host': ftp_host, 'path': remote_path, 'type': 'directory'}
            else:
                bio = BytesIO()
                ftp.retrbinary(f'RETR {remote_path}', bio.write)
                result = bio.getvalue()
                metadata = {'host': ftp_host, 'path': remote_path, 'type': 'file', 'size': len(result)}
            ftp.quit()
            return result, metadata
        except Exception as e:
            if is_permanent_failure(e):
                raise ValueError(f"Permanent FTP failure: {e}") from e
            logging.warning(f"FTP attempt {attempt}/{max_retries} failed for {url}: {e}")
            if attempt == max_retries:
                raise # Re-raise the final exception
            time.sleep(backoff_base * 2 ** (attempt - 1))
    raise ValueError("FTP fetch failed after all retries.")

# --- File Helper (No Retry Needed) ---
def _fetch_file(url: str, base_dir: Optional[str]) -> Tuple[bytes, Dict[str, Any]]:
    effective_base_dir = base_dir if base_dir is not None else os.getcwd()
    file_path = os.path.abspath(os.path.join(effective_base_dir, urlparse(url).path.lstrip('/\\')))
    if not file_path.startswith(os.path.abspath(effective_base_dir)):
        raise ValueError('Security Error: Path traversal attempt detected.')
    with open(file_path, 'rb') as f:
        content = f.read()
    metadata = {'path': file_path, 'size': len(content)}
    return content, metadata

# --- Main Dispatcher Function ---
def fetch(url: str, output: list, headers: Optional[Dict] = None, timeout_seconds: Optional[int] = None, username: str = 'anonymous', password: str = '', passive_mode: bool = True, base_dir: Optional[str] = None) -> tuple:
    try:
        scheme = urlparse(url).scheme
        if scheme in ['http', 'https']: handler, args = _fetch_http, (url, headers, timeout_seconds)
        elif scheme in ['ftp', 'ftps']: handler, args = _fetch_ftp, (url, username, password, passive_mode)
        elif scheme == 'file': handler, args = _fetch_file, (url, base_dir)
        else: return {}, {"status": {"value": 1, "reason": f"Unsupported protocol scheme: '{scheme}'"}}
        content, metadata = handler(*args)
        result_dict = {output[0]: content}
        if len(output) > 1: result_dict[output[1]] = metadata
        return result_dict, {"status": {"value": 0, "reason": "Success"}}
    except Exception as e:
        logging.error(f"Fetch failed for URL '{url}': {e}", exc_info=False)
        return {}, {"status": {"value": 1, "reason": f"Failed to fetch data: {e}"}}

