def ftp_fetch(
    remote_path: str,
    ftp_host: str,
    output: list,
    ftp_user: str = "anonymous",
    ftp_pass: str = "",
    port: int = 21,
    passive_mode: bool = True,
) -> tuple:
    """
    Fetch a file or directory listing from FTP server.

    Parameters:
        remote_path: str - path on FTP server (ends with '/' if directory)
        ftp_host: str - FTP server hostname
        output: list - list of output variable names (ignored here)
        ftp_user: str - optional username (empty for anonymous)
        ftp_pass: str - optional password
        port: int - FTP port (default 21)
        passive_mode: bool - passive mode toggle (default True)

    Returns:
        tuple: (raw_data, status_dict)
            raw_data: bytes if file, str if directory listing
            status_dict: dict with "status": {"value": 0 or 1, "reason": "message"}
    """
    import time
    from ftplib import FTP, error_perm
    from io import BytesIO
    from os.path import dirname, basename
    import socket

    MAX_RETRIES = 5
    BACKOFF_BASE = 1

    def is_permanent_failure(e: Exception) -> bool:
        msg = str(e).lower()
        if isinstance(e, error_perm):
            return any(code in msg for code in ["550", "530", "553", "501", "502"])
        return False

    def connect_ftp(use_auth: bool, passive: bool) -> FTP:
        ftp = FTP()
        ftp.connect(ftp_host, port, timeout=10)
        if use_auth and ftp_user:
            ftp.login(user=ftp_user, passwd=ftp_pass)
        else:
            ftp.login()
        ftp.set_pasv(passive)
        return ftp

    def get_directory(ftp: FTP) -> str:
        lines = []
        ftp.cwd(remote_path)
        ftp.retrlines("NLST", lines.append)
        return "\n".join(lines)

    def get_file(ftp: FTP) -> bytes:
        dirpath = dirname(remote_path)
        fname = basename(remote_path)
        if dirpath and dirpath != "/":
            ftp.cwd(dirpath)
        buf = BytesIO()
        ftp.retrbinary(f"RETR {fname}", buf.write)
        return buf.getvalue()

    for attempt in range(1, MAX_RETRIES + 1):
        try:
            use_auth = (attempt % 2 == 1)
            current_passive = passive_mode if attempt <= 3 else not passive_mode

            ftp = connect_ftp(use_auth, current_passive)

            if remote_path.endswith("/"):
                result = get_directory(ftp)
            else:
                result = get_file(ftp)

            ftp.quit()
            return result, {"status": {"value": 0, "reason": "Success"}}

        except Exception as e:
            if is_permanent_failure(e):
                return None, {"status": {"value": 1, "reason": f"Permanent failure: {str(e)}"}}
            if attempt == MAX_RETRIES:
                return None, {"status": {"value": 1, "reason": f"Max retries reached: {str(e)}"}}
            time.sleep(BACKOFF_BASE * 2 ** (attempt - 1))

