import requests
import time
import json
import re
import logging
from typing import Dict, Union, Optional
from urllib.parse import urlparse

def _is_hostname_private(hostname: str) -> bool:
    """Checks if a given hostname resolves to a private or reserved IP."""
    if not hostname: return True # Treat empty hostname as unsafe
    private_ip_pattern = re.compile(
        r"^((127\.)|(10\.)|(172\.(1[6-9]|2[0-9]|3[0-1])\.)|(192\.168\.)|(0\.)|(169\.254\.))" 
        r"|^(localhost)$"
    )
    return bool(private_ip_pattern.match(hostname))

def smart_http_get(url: str, output:list, headers: Dict[str, str] = None, timeout_seconds: Optional[int] = None) -> tuple[bytes, Dict[str, Dict[str, Union[int, str]]]]:
    """Performs an HTTP GET request, automatically toggling security based on protocol."""

    is_secure_protocol = url.lower().startswith('https://')

    if is_secure_protocol:
        # --- SECURE MODE for https:// ---
        effective_timeout = int(timeout_seconds) if timeout_seconds is not None else 30
        try:
            parsed_url = urlparse(url)
            if _is_hostname_private(parsed_url.hostname):
                return b"", {"status": {"value": 1, "reason": "Security Error: HTTPS URL targets a forbidden internal or private IP address."}}
        except Exception as e:
            return b"", {"status": {"value": 1, "reason": f"URL parsing error: {e}"}}
    else:
        # --- INSECURE MODE for http:// ---
        effective_timeout = int(timeout_seconds) if timeout_seconds is not None else 600

    # Shared request and retry logic
    max_retries: int = 3
    retry_delays = [5, 10, 15]
    headers_dict = json.loads(headers) if isinstance(headers, str) and headers else headers or {}

    for attempt in range(max_retries):
        try:
            response = requests.get(url, headers=headers_dict, timeout=effective_timeout)
            if response.status_code == 200:
                return response.content, {"status": {"value": 0, "reason": "Success"}}
            if attempt < max_retries - 1:
                time.sleep(retry_delays[attempt])
                continue
            return b"", {"status": {"value": 1, "reason": f"{response.status_code} HTTP Error after {max_retries} attempts."}}
        except requests.exceptions.RequestException as e:
            logging.error(f"Request for {url} failed: {e}")
            if attempt < max_retries - 1:
                time.sleep(retry_delays[attempt])
                continue
            return b"", {"status": {"value": 1, "reason": f"Request failed: {e}"}}

    return b"", {"status": {"value": 1, "reason": "Request failed after max retries."}}

